mod doc_index_select {
    use super::*;
    static FUNC: &str = "doc_index_select";

    #[test]
    fn test_doc() {
        crate::specify_test!("test_doc");
        let mut device = TESTCFG.device.clone();
        device.set_default_order(RowMajor);

        let a = rt::arange((12, &device)).into_shape([3, 4]);

        // array of indices
        println!("{}", rt::index_select(&a, 0, [0, 2]));
        // [[ 0 1 2 3]
        //  [ 8 9 10 11]]
        assert_eq!(format!("{}", rt::index_select(&a, 0, [0, 2])), "[[ 0 1 2 3]\n [ 8 9 10 11]]");

        // Vec of indices
        println!("{}", rt::index_select(&a, 1, vec![3, 1]));
        // [[ 3 1]
        //  [ 7 5]
        //  [ 11 9]]
        assert_eq!(format!("{}", rt::index_select(&a, 1, vec![3, 1])), "[[ 3 1]\n [ 7 5]\n [ 11 9]]");

        // borrowed slice / Vec of indices
        let id: &[isize] = &[0, 2];
        println!("{}", rt::index_select(&a, 0, id));
        // [[ 0 1 2 3]
        //  [ 8 9 10 11]]
        assert_eq!(format!("{}", rt::index_select(&a, 0, id)), "[[ 0 1 2 3]\n [ 8 9 10 11]]");
        let idv: Vec<isize> = vec![0, 2];
        assert_eq!(format!("{}", rt::index_select(&a, 0, &idv)), "[[ 0 1 2 3]\n [ 8 9 10 11]]");

        // single integer; negative counts from the back
        println!("{}", rt::index_select(&a, 0, -1));
        // [[ 8 9 10 11]]
        assert_eq!(format!("{}", rt::index_select(&a, 0, -1)), "[[ 8 9 10 11]]");
    }
}

