mod doc_bool_select {
    use super::*;
    static FUNC: &str = "doc_bool_select";

    #[test]
    fn test_doc() {
        crate::specify_test!("test_doc");
        let mut device = TESTCFG.device.clone();
        device.set_default_order(RowMajor);

        let a = rt::arange((12, &device)).into_shape([3, 4]);

        // array of bool
        println!("{}", rt::bool_select(&a, 1, [true, false, true, false]));
        // [[ 0 2]
        //  [ 4 6]
        //  [ 8 10]]
        assert_eq!(format!("{}", rt::bool_select(&a, 1, [true, false, true, false])), "[[ 0 2]\n [ 4 6]\n [ 8 10]]");

        // Vec of bool
        let m: Vec<bool> = vec![true, false, false];
        println!("{}", rt::bool_select(&a, 0, m));
        // [[ 0 1 2 3]]
        assert_eq!(format!("{}", rt::bool_select(&a, 0, vec![true, false, false])), "[[ 0 1 2 3]]");

        // single bool: one flag, selecting position 0 when true
        println!("{}", rt::bool_select(&a, 1, true));
        // [[ 0]
        //  [ 4]
        //  [ 8]]
        assert_eq!(format!("{}", rt::bool_select(&a, 1, true)), "[[ 0]\n [ 4]\n [ 8]]");
    }
}

mod doc_take_along_axis {
    use super::*;
    static FUNC: &str = "doc_take_along_axis";

    #[test]
    fn test_doc() {
        crate::specify_test!("test_doc");
        let mut device = TESTCFG.device.clone();
        device.set_default_order(RowMajor);

        let a = rt::tensor_from_nested!([[10, 20, 30], [40, 50, 60]], &device);
        let idx = rt::tensor_from_nested!([[2, 0], [1, 1]], &device);

        // explicit negative axis
        println!("{}", rt::take_along_axis(&a, &idx, -1));
        // [[ 30 10]
        //  [ 50 50]]
        assert_eq!(format!("{}", rt::take_along_axis(&a, &idx, -1)), "[[ 30 10]\n [ 50 50]]");

        // explicit positive axis
        assert_eq!(format!("{}", rt::take_along_axis(&a, &idx, 1)), "[[ 30 10]\n [ 50 50]]");

        // axis = None (or ()) selects the last axis
        println!("{}", rt::take_along_axis(&a, &idx, None));
        // [[ 30 10]
        //  [ 50 50]]
        assert_eq!(format!("{}", rt::take_along_axis(&a, &idx, None)), "[[ 30 10]\n [ 50 50]]");
        assert_eq!(format!("{}", rt::take_along_axis(&a, &idx, ())), "[[ 30 10]\n [ 50 50]]");

        // axis = 0: gather along the leading axis
        let idx0 = rt::tensor_from_nested!([[1, 0, 0], [0, 1, 1]], &device);
        println!("{}", rt::take_along_axis(&a, &idx0, 0));
        // [[ 40 20 30]
        //  [ 10 50 60]]
        assert_eq!(format!("{}", rt::take_along_axis(&a, &idx0, 0)), "[[ 40 20 30]\n [ 10 50 60]]");
    }
}

mod doc_index_put {
    use super::*;
    static FUNC: &str = "doc_index_put";

    #[test]
    fn test_doc() {
        crate::specify_test!("test_doc");
        let mut device = TESTCFG.device.clone();
        device.set_default_order(RowMajor);

        // array of indices
        let mut a: Tensor<i32, _> = rt::zeros(([3, 2], &device));
        let vals = rt::tensor_from_nested!([[1, 2], [3, 4]], &device);
        rt::index_put(&mut a, 0, [0, 2], &vals);
        println!("{a}");
        // [[ 1 2]
        //  [ 0 0]
        //  [ 3 4]]
        assert_eq!(format!("{a}"), "[[ 1 2]\n [ 0 0]\n [ 3 4]]");

        // Vec of indices
        let mut b: Tensor<i32, _> = rt::zeros(([3, 2], &device));
        rt::index_put(&mut b, 0, vec![0, 2], &vals);
        assert_eq!(format!("{b}"), "[[ 1 2]\n [ 0 0]\n [ 3 4]]");

        // single integer; negative counts from the back
        let mut c: Tensor<i32, _> = rt::arange((6, &device)).into_shape([3, 2]);
        let row = rt::tensor_from_nested!([9, 9], &device);
        rt::index_put(&mut c, 0, -1, &row);
        println!("{c}");
        // [[ 0 1]
        //  [ 2 3]
        //  [ 9 9]]
        assert_eq!(format!("{c}"), "[[ 0 1]\n [ 2 3]\n [ 9 9]]");
    }
}

mod doc_put_along_axis {
    use super::*;
    static FUNC: &str = "doc_put_along_axis";

    #[test]
    fn test_doc() {
        crate::specify_test!("test_doc");
        let mut device = TESTCFG.device.clone();
        device.set_default_order(RowMajor);

        let idx = rt::tensor_from_nested!([[2isize, 0], [1, 1]], &device);
        let vals = rt::tensor_from_nested!([[30, 10], [50, 50]], &device);

        // explicit negative axis
        let mut a: Tensor<i32, _> = rt::zeros(([2, 3], &device));
        rt::put_along_axis(&mut a, &idx, &vals, -1);
        println!("{a}");
        // [[ 10 0 30]
        //  [ 0 50 0]]
        assert_eq!(format!("{a}"), "[[ 10 0 30]\n [ 0 50 0]]");

        // axis = None (or ()) selects the last axis
        let mut b: Tensor<i32, _> = rt::zeros(([2, 3], &device));
        rt::put_along_axis(&mut b, &idx, &vals, None);
        assert_eq!(format!("{b}"), "[[ 10 0 30]\n [ 0 50 0]]");

        // explicit positive axis
        let mut c: Tensor<i32, _> = rt::zeros(([2, 3], &device));
        rt::put_along_axis(&mut c, &idx, &vals, 1);
        assert_eq!(format!("{c}"), "[[ 10 0 30]\n [ 0 50 0]]");
    }
}
